const fresh=()=>{const p=structuredClone(fixture);p.parameter_index=buildAtomicParameterIndex(p);return p;};
test('A omitted facts fail without default-filled report_project',()=>{const r=buildFrozenReportProject({});assert.equal(r.reportProject,null);assert.ok(r.missing.some(x=>x.startsWith('name')));assert.ok(r.missing.some(x=>x.startsWith('roomDims')));assert.ok(r.missing.some(x=>x.startsWith('screen')));});
test('B selected Level 4 frozen facts agree',()=>{const p=fresh();assert.equal(auditPublicationContract(p).allowed,true);assert.equal(p.report_snapshot.report_project.name,'Marquee Home');assert.deepEqual(p.report_snapshot.report_project.seats_per_row_by_row,[4,5]);assert.equal(p.report_snapshot.report_project.screen_width_m,4.318);});
test('C old same-result publications rejected by contract',()=>{const p=fresh();delete p.publication_contract_version;assert.equal(auditPublicationContract(p).allowed,false);assert.equal(auditEngineeringPublication(p).durablyPublished,false);});
test('C contract revision changes publication identity',()=>{const a=computeEngineeringFingerprint({}, {publicationContractVersion:1}), b=computeEngineeringFingerprint({}, {publicationContractVersion:PUBLICATION_CONTRACT_VERSION});assert.notEqual(a,b);});
test('D all P1–P21 persisted atomic source rows',()=>{const p=fresh();assert.equal(Object.keys(p.parameter_index).length,21);for(const item of Object.values(p.parameter_index)){assert.ok(item.authority_fingerprint);assert.ok(item.source_row);assert.equal(item.raw_value,item.source_row.value??item.source_row.rawValue??null);}});
test('D P10 scope and associated value never mixed',()=>{const p=fresh(),x=p.parameter_index.P10;assert.equal(x.scope,'project');assert.equal(x.raw_value,9);assert.equal(x.level,'L1');assert.equal(x.scopes.primary.raw_value,4);assert.equal(x.scopes.primary.level,'L3');assert.equal(x.supporting_per_seat.length,9);});
test('D P14 selected B118 authority is 118 / L4',()=>{const p=fresh(),x=p.parameter_index.P14;assert.equal(x.raw_value,118);assert.equal(x.level,'L4');assert.equal(x.authority_fingerprint,p.provenance.bass_fingerprint);});
test('E contradictory row count rejected by both readers',()=>{const p=fresh();p.report_snapshot.report_project.seating_rows=1;const a=auditEngineeringPublication(p),b=auditPublicationEntry(p);assert.equal(a.complete,false);assert.deepEqual(a.missing.map(x=>x.key),b.missing.map(x=>x.key));assert.ok(a.missing.some(x=>x.key.includes('seating_rows')));});
test('E conflicting 5.1 layout rejected',()=>{const p=fresh();p.report_snapshot.report_project.dolby_config='5.1';assert.ok(auditPublicationContract(p).missing.some(x=>x.includes('dolby_config')));});
test('E parameter level/provenance tampering rejected',()=>{const p=fresh();p.parameter_index.P14.level='L3';p.parameter_index.P10.authority_fingerprint='wrong';assert.equal(auditPublicationContract(p).allowed,false);});
test('F final report regeneration blocks old or incomplete authority',()=>{assert.equal(auditFinalReportAuthority(fixture).allowed,false);assert.equal(auditFinalReportAuthority(fresh()).allowed,true);});
test('server/client contract byte parity',()=>{assert.equal(readFileSync('shared/engineeringPublicationContract.js','utf8'),readFileSync('base44/shared/engineeringPublicationContract.js','utf8'));});
